return {["fb32_01"]={["dsc"]=[[这是澜沧江边的一条小路，江水滔滔，从下面奔腾而过，江面上不时传来艄公的号子声，与江风的呼啸声形成一曲动人的交响乐。]],["fightBackground"]=[[山内]],["id"]=[[fb32_01]],["name"]=[[江边小路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb32_05]]},["fb32_02"]={["dsc"]=[[这是一条山间小路，两边山坡上长了许多树木，北风吹过，发出沙沙的响声。路上长着许多杂草，看起来这里很少有人走动。]],["fightBackground"]=[[山外]],["id"]=[[fb32_02]],["item1"]=[[fb32item19]],["item2"]=[[fb32item19]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb32_03]],["stepMusic"]=[[jiaobu]],["up"]=[[fb32_06]]},["fb32_03"]={["dsc"]=[[这是一条山间小路，两边山坡上长了许多树木，北风吹过，发出沙沙的响声。路上长着许多杂草，看起来这里很少有人走动。]],["fightBackground"]=[[山外]],["id"]=[[fb32_03]],["item1"]=[[fb32item1]],["item2"]=[[fb32item19]],["left"]=[[fb32_02]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb32_04]],["role1"]=[[fb32r03_1]],["role2"]=[[2019qxcdg1a]],["role3"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]]},["fb32_04"]={["dsc"]=[[这是一条山间小路，两边山坡上长了许多树木，北风吹过，发出沙沙的响声。路上长着许多杂草，看起来这里很少有人走动。]],["fightBackground"]=[[山外]],["id"]=[[fb32_04]],["item1"]=[[fb32item19]],["item2"]=[[fb32item19]],["left"]=[[fb32_03]],["name"]=[[山路]],["permission"]=1,["role1"]=[[fb32r04_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb32_07]]},["fb32_05"]={["down"]=[[fb32_01]],["dsc"]=[[这是澜沧江边的一条小路，江水滔滔，从下面奔腾而过，江面上不时传来艄公的号子声，与江风的呼啸声形成一曲动人的交响乐。]],["fightBackground"]=[[山内]],["id"]=[[fb32_05]],["item1"]=[[fb32zmdj]],["name"]=[[江边小路]],["permission"]=2,["role1"]=[[fb32r05_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb32_10]]},["fb32_06"]={["down"]=[[fb32_02]],["dsc"]=[[这是一条山间小路，两边山坡上长了许多树木，北风吹过，发出沙沙的响声。路上长着许多杂草，看起来这里很少有人走动。]],["fightBackground"]=[[山外]],["id"]=[[fb32_06]],["name"]=[[山路]],["permission"]=1,["role1"]=[[fb32r06_1]],["role2"]=[[fb32r06_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb32_12]]},["fb32_07"]={["down"]=[[fb32_04]],["dsc"]=[[这是一条山间小路，两边山坡上长了许多树木，北风吹过，发出沙沙的响声。路上长着许多杂草，看起来这里很少有人走动。]],["fightBackground"]=[[山外]],["id"]=[[fb32_07]],["item1"]=[[fb32item18]],["item2"]=[[fb32item19]],["name"]=[[山路]],["permission"]=2,["right"]=[[fb32_08]],["stepMusic"]=[[jiaobu]]},["fb32_08"]={["dsc"]=[[这里是一个小山坡，西面是上山的路，东面一条铁索桥横跨江面，只见江水奔腾，呼啸而过，江风吹得铁索桥晃来晃去。]],["fightBackground"]=[[山内]],["id"]=[[fb32_08]],["item1"]=[[fb32item19]],["item2"]=[[fb32item19]],["item3"]=[[bfitem1]],["left"]=[[fb32_07]],["name"]=[[澜沧江畔]],["permission"]=2,["right"]=[[fb32_09]],["stepMusic"]=[[jiaobu]]},["fb32_09"]={["dsc"]=[[一座横跨澜沧江的铁索桥，此桥共有四道铁索，两条在下，上铺木板，以供行走，两条在旁，作为扶手。一踏上桥，几条铁索便即晃动。]],["fightBackground"]=[[山内]],["id"]=[[fb32_09]],["left"]=[[fb32_08]],["name"]=[[铁索桥]],["permission"]=2,["right"]=[[fb32_10]],["role1"]=[[fb32r09_100]],["stepMusic"]=[[jiaobu]]},["fb32_10"]={["down"]=[[fb32_05]],["dsc"]=[[这里从前是澜沧江的一个渡口，后来大理国在此修了一座铁索桥，人们便不用再乘船过江了。桥边石上清清楚楚地刻着三个大字“善人渡”。]],["fightBackground"]=[[山内]],["id"]=[[fb32_10]],["left"]=[[fb32_09]],["name"]=[[善人渡]],["permission"]=2,["right"]=[[fb32_11]],["role1"]=[[fb32r10_1]],["role2"]=[[fb32r10_2]],["role3"]=[[zybrr10_01]],["role4"]=[[zybrr10_02]],["stepMusic"]=[[jiaobu]]},["fb32_11"]={["dsc"]=[[这是澜沧江边的一条小路，江水滔滔，从下面奔腾而过，江面上不时传来艄公的号子声，与江风的呼啸声形成一曲动人的交响乐。]],["fightBackground"]=[[山内]],["id"]=[[fb32_11]],["item1"]=[[fb32item100]],["item2"]=[[2019qxhdd1]],["left"]=[[fb32_10]],["name"]=[[江边小路]],["permission"]=2,["role1"]=[[fb32r11_1]],["stepMusic"]=[[jiaobu]]},["fb32_12"]={["down"]=[[fb32_06]],["dsc"]=[[这里是好大一座森林，黑压压的一片望不到边。最特别是左首一排并列着九株参天大松树，每颗树都高耸入云。树下草丛茂密，挡住了去路。]],["fightBackground"]=[[森林内]],["id"]=[[fb32_12]],["item1"]=[[fb32item6]],["name"]=[[大森林]],["permission"]=1,["role1"]=[[fb32r12_1]],["role2"]=[[fb32item6]],["role3"]=[[fb32item6]],["role4"]=[[fb32item6]],["stepMusic"]=[[jiaobu]],["up"]=[[fb32_22]]},["fb32_13"]={["down"]=[[fb32_30]],["dsc"]=[[这是一大片草地，前面一排松树挡住了去路。只见一株大松上削下了丈许长、尺许宽的一片，漆着白漆，写着九个大字，“姓段者入此谷杀无赦”。树上挂着一个铁锤。]],["id"]=[[fb32_13]],["item1"]=[[fb32item3]],["item2"]=[[fb32item12]],["item3"]=[[ycitem1]],["name"]=[[草地]],["permission"]=1,["role1"]=[[fb32r13_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb32_14]]},["fb32_14"]={["down"]=[[fb32_13]],["dsc"]=[[这是一间小厅，桌上点着一对巨烛。东壁四幅屏条，绘的是梅兰竹菊，西壁上的四幅是春夏秋冬。可是全挂错了方位，看来这里的主人并不懂得书画。]],["id"]=[[fb32_14]],["name"]=[[小厅]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb32_16]]},["fb32_15"]={["dsc"]=[[这是一间普通的房间，里面放着一些日常用品。桌子上放着一壶茶，还没有冷掉。旁边一个大柜子，里面放着许多衣服。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb32_15]],["item1"]=[[fb32item13]],["name"]=[[左厢房]],["permission"]=2,["right"]=[[fb32_16]],["stepMusic"]=[[jiaobu]],["up"]=[[fb32_18]]},["fb32_16"]={["down"]=[[fb32_14]],["dsc"]=[[这里放着一张大桌子，靠墙有两张凳子，白白的墙壁一尘不染，有一个人正在屋里走来走去，显的心情焦躁。]],["id"]=[[fb32_16]],["item1"]=[[fb32item2]],["left"]=[[fb32_15]],["name"]=[[内堂]],["permission"]=1,["right"]=[[fb32_17]],["role1"]=[[fb32r16_1]],["role2"]=[[fb32r16_2]],["role3"]=[[fb32r16_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb32_19]]},["fb32_17"]={["dsc"]=[[这是一间普通的房间，里面放着一些日常用品，墙角落里堆着一堆药草，是殷谷主采集而来，日后要用它制造各种药物。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb32_17]],["left"]=[[fb32_16]],["name"]=[[右厢房]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb32_20]]},["fb32_18"]={["down"]=[[fb32_15]],["dsc"]=[[这是殷谷主的卧室，室内大红的帏帐挂在大红的木床之上。墙上贴满了各种花花绿绿的东西。床边有个小柜，柜上放着一盏豆油灯。]],["id"]=[[fb32_18]],["item1"]=[[fb32item7]],["item2"]=[[fb32item8]],["item3"]=[[fb32item14]],["item4"]=[[ycitem6]],["name"]=[[卧室]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb32_19"]={["down"]=[[fb32_16]],["dsc"]=[[后院是一大片开阔的草地，绿草如荫，几朵野花点缀其间，草地中间放着一块大石刻成的棋盘。]],["id"]=[[fb32_19]],["item1"]=[[fb32item4]],["name"]=[[后院]],["permission"]=1,["role1"]=[[fb32r19_1]],["role2"]=[[fb32r19_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb32_21]]},["fb32_20"]={["down"]=[[fb32_17]],["dsc"]=[[刚进这间屋子，就有一股浓重的药味扑面而来。房子中间有一个练药用的石臼，还有几只药匙放在一边。]],["id"]=[[fb32_20]],["item1"]=[[fb32item9]],["item2"]=[[fb32item10]],["name"]=[[药房]],["permission"]=2,["role1"]=[[fb32r20_3]],["stepMusic"]=[[jiaobu]]},["fb32_21"]={["down"]=[[fb32_19]],["dsc"]=[[一间用花岗岩砌成的房子，坚固无比。南面有一个小孔，西边有一张小床，屋内光线黑暗，又有些潮湿。]],["id"]=[[fb32_21]],["item1"]=[[fb32item5]],["name"]=[[石屋]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb32_22"]={["down"]=[[fb32_12]],["dsc"]=[[这里是好大一座森林，黑压压的一片望不到边。最特别是左首一排并列着九株参天大松树，每颗树都高耸入云。树下草丛茂密，挡住了去路。]],["fightBackground"]=[[森林内]],["id"]=[[fb32_2